use vstd::prelude::*;

verus! {

spec fn vec_elements_eq<T: Copy + PartialEq>(v1: &Vec<T>, v2: &Vec<T>) -> bool
    requires
        v1@.len() == v2@.len(),
{
    forall|i: int| (0 <= i && i < v1@.len()) ==> (v1@[i] == v2@[i])
}

fn copy<T: Copy>(a: &Vec<T>) -> (result: Vec<T>)
    ensures
        result.len() == a.len(),
        vec_elements_eq(&result, a),
        // input not modified
        a@.len() == a.len(),
{
    let mut res = Vec::new();
    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            res.len() == i,
            // for all indices copied so far the elements equal the input
            forall|j: int| (0 <= j && j < i as int) ==> res[j] == a[j],
            a@.len() == a.len(),
        decreases a.len() - i,
    {
        res.push(a[i]);
        i = i + 1;
    }
    result = res;
}

} 
